// КОНСТАНТЫ (без магических чисел)
// ============================================================

static constexpr Uint8 FALLBACK_BG_R = 40;
static constexpr Uint8 FALLBACK_BG_G = 40;
static constexpr Uint8 FALLBACK_BG_B = 50;
static constexpr Uint8 FALLBACK_BG_A = 255;

// Формат кода тайла — XXYVRRF, позиция 2 — буква формы (shape).
static constexpr std::size_t TILE_CODE_MIN_LEN   = 3;
static constexpr std::size_t TILE_SHAPE_CHAR_IDX = 2;

static constexpr float HALF_TILE = TILE_SIZE / 2.0f;

// --- Треугольный slope-коллайдер лестницы ---
// Гипотенуза идёт от нижней ступени (у пола) до верхней площадки.
// Координаты взяты из физ-слоя: ступени "5" занимают col 25..32,
// верхняя ступень — row 19, пол под нижней ступенью — row 27.
static constexpr int STAIRS_COL_MIN    = 25;
static constexpr int STAIRS_COL_MAX    = 32;
static constexpr int STAIRS_TOP_ROW    = 19;
static constexpr int STAIRS_GROUND_ROW = 27;
// Зона ОБНАРУЖЕНИЯ пандуса шире самого уклона на 1 тайл вправо —
// без этого на стыке с верхней площадкой была мёртвая зона без опоры
// (хитбокс игрока шире 1 тайла, а зона снапа заканчивалась ровно на
// последней ступеньке), из-за чего требовался прыжок на верхний этаж.
static constexpr int STAIRS_DETECT_MARGIN_TILES = 1;

