// ============================================================
// СМЕЩЕНИЕ КАРТЫ (центрирование на экране)
// ============================================================

void Level3::getL3MapOffset(int& ox, int& oy) {
    ox = (Config::getWindowWidth()  - WIDTH_TILES  * TILE_SIZE) / 2;
    oy = (Config::getWindowHeight() - HEIGHT_TILES * TILE_SIZE) / 2;
}

void Level3::getMapOffset(int& outX, int& outY) {
    getL3MapOffset(outX, outY);
}

// ============================================================
// ОТРИСОВКА — порядок: BG → SOLID → DECO
// ============================================================

void Level3::drawMap(SDL_Renderer* renderer, int camX, int camY) {
    SDL_Texture* tileset = TextureManager::getTexture("assets/map1/map1.png");

    int ox, oy;
    getL3MapOffset(ox, oy);
    ox -= camX;
    oy -= camY;

    if (!tileset) {
        SDL_SetRenderDrawColor(renderer, FALLBACK_BG_R, FALLBACK_BG_G, FALLBACK_BG_B, FALLBACK_BG_A);
        SDL_Rect fb = {ox, oy, WIDTH_TILES * TILE_SIZE, HEIGHT_TILES * TILE_SIZE};
        SDL_RenderFillRect(renderer, &fb);
        return;
    }

    for (int row = 0; row < HEIGHT_TILES; row++)
        for (int col = 0; col < WIDTH_TILES; col++)
            if (!LEVEL3_BG[row][col].empty())
                drawTileByCode(renderer, tileset, LEVEL3_BG[row][col],
                               ox + col * TILE_SIZE, oy + row * TILE_SIZE);

    for (int row = 0; row < HEIGHT_TILES; row++)
        for (int col = 0; col < WIDTH_TILES; col++)
            if (!LEVEL3_SOLID[row][col].empty())
                drawTileByCode(renderer, tileset, LEVEL3_SOLID[row][col],
                               ox + col * TILE_SIZE, oy + row * TILE_SIZE);

    for (int row = 0; row < HEIGHT_TILES; row++)
        for (int col = 0; col < WIDTH_TILES; col++)
            if (!LEVEL3_DECO[row][col].empty())
                drawTileByCode(renderer, tileset, LEVEL3_DECO[row][col],
                               ox + col * TILE_SIZE, oy + row * TILE_SIZE);
}

// ============================================================
// КОЛЛИЗИИ
// ============================================================

bool Level3::isSolid(int worldX, int worldY) {
    int ox, oy;
    getL3MapOffset(ox, oy);
    int col = (worldX - ox) / TILE_SIZE;
    int row = (worldY - oy) / TILE_SIZE;
    if (col < 0 || col >= WIDTH_TILES || row < 0 || row >= HEIGHT_TILES) return true;

    const std::string& code = LEVEL3_SOLID[row][col];
    if (code.size() < TILE_CODE_MIN_LEN) return false;
    if (code[0] == 's' && code[1] == 'p') return false;  // платформы миньонов — не solid-стена
    if (code[0] == 's' && code[1] == 's') return false;  // ступени лестницы — коллизия через getStairGroundY(), не блок

    char shape = code[TILE_SHAPE_CHAR_IDX];
    return (shape == 'w' || shape == 'f' || shape == 'c');
}

bool Level3::isPlatform(int worldX, int worldY) {
    int ox, oy;
    getL3MapOffset(ox, oy);
    int col = (worldX - ox) / TILE_SIZE;
    int row = (worldY - oy) / TILE_SIZE;
    if (col < 0 || col >= WIDTH_TILES || row < 0 || row >= HEIGHT_TILES) return false;

    const std::string& code = LEVEL3_SOLID[row][col];
    return (code.size() >= 2 && code[0] == 's' && code[1] == 'p');
}

// ============================================================
// ЛЕСТНИЦА — треугольный slope-коллайдер
// ============================================================
//
//   topY  ┌──────────── верхняя площадка (row 19)
//         │╲
//         │ ╲   ← гипотенуза (обращена к ступенькам)
//         │  ╲
// groundY └───╲──────── пол (row 27)
//       leftX  rightX
//
// Прямой угол — внизу-справа (у пола, у самой правой/верхней ступени).
// Уклон ровно 1:1 (45°): 8 тайлов по X, 8 тайлов по Y.

bool Level3::getStairGroundY(float pixelX, float& outGroundY) {
    int ox, oy;
    getL3MapOffset(ox, oy);

    // leftX/rightX — истинные границы 45° уклона (форма треугольника не меняется).
    const float leftX  = static_cast<float>(ox + STAIRS_COL_MIN * TILE_SIZE);
    const float rightX = static_cast<float>(ox + (STAIRS_COL_MAX + 1) * TILE_SIZE);

    // rightXDetect — граница ОБНАРУЖЕНИЯ, с запасом на верхнюю площадку (см. комментарий у константы).
    const float rightXDetect = rightX + STAIRS_DETECT_MARGIN_TILES * TILE_SIZE;
    if (pixelX < leftX || pixelX > rightXDetect) return false;

    const float groundY = static_cast<float>(oy + STAIRS_GROUND_ROW * TILE_SIZE);
    const float topY    = static_cast<float>(oy + STAIRS_TOP_ROW    * TILE_SIZE);

    // За пределами leftX..rightX (в запасной зоне) clamp сам выравнивает в topY —
    // угол уклона от этого не меняется, там просто плоская "полка".
    outGroundY = groundY - (pixelX - leftX);
    outGroundY = std::clamp(outGroundY, topY, groundY);
    return true;
}

// ============================================================
// СПАВНЫ
// ============================================================

std::pair<float, float> Level3::getPlayerSpawn() {
    int ox, oy;
    getL3MapOffset(ox, oy);
    return { ox + L3_PLAYER_COL * TILE_SIZE + HALF_TILE,
            oy + L3_PLAYER_ROW * TILE_SIZE + HALF_TILE };
}

std::pair<float, float> Level3::getBossSpawn() {
    int ox, oy;
    getL3MapOffset(ox, oy);
    return { ox + L3_BOSS_COL * TILE_SIZE + HALF_TILE,
            oy + L3_BOSS_ROW * TILE_SIZE + HALF_TILE };
}

std::unique_ptr<Character> Level3::createBoss(float x, float y, float attackSpeedMult) {
    return std::make_unique<BossDeadNight>(x, y, attackSpeedMult);
}

std::pair<float, float> Level3::getMinionSpawn(int index) const {
    int ox, oy;
    getL3MapOffset(ox, oy);
    const auto& p = LEVEL3_MINION_SPAWNS[index];
    return { ox + p.col * TILE_SIZE + HALF_TILE,
            oy + p.row * TILE_SIZE + HALF_TILE };
}

int Level3::getMinionCount() const {
    return MINION_COUNT;
}

