std::string Level3::getMusicName() { return "level3_music"; }
std::string Level3::getLevelName() { return "Уровень 3: Летающий страж"; }

int Level3::getMapWidth()  const { return WIDTH_TILES  * TILE_SIZE; }
int Level3::getMapHeight() const { return HEIGHT_TILES * TILE_SIZE; }